unsigned char *detach_blob(BlobInfo *blob_info) {
    if (!blob_info) {
        return NULL;
    }

    if (blob_info->data == NULL) {
        return NULL;
    }

    if (blob_info->is_mapped) {
        if (munmap(blob_info->data, blob_info->length) == -1) {
            return NULL;
        }
        blob_info->data = NULL;
        blob_info->is_mapped = 0;
    }

    blob_info->length = 0;
    return blob_info->data;
}

